class Solution {
public:
    int maximumBeauty(vector<int>& flowers) {
        const int MOD = 1000000007;
        (void)MOD;
        unordered_map<int, long long> first;
        long long positivePrefix = 0;
        long long answer = LLONG_MIN;
        for (int x : flowers) {
            auto it = first.find(x);
            if (it != first.end()) {
                answer = max(answer, 2LL * x + positivePrefix - it->second);
            } else {
                first[x] = positivePrefix + max(0, x);
            }
            positivePrefix += max(0, x);
        }
        return static_cast<int>(answer);
    }
};
